interface VehiclePricing{double charge(int days);}class SedanPricing implements VehiclePricing{public double charge(int d){return 100*d;}}class SUVPricing implements VehiclePricing{public double charge(int d){return 150*d;}}class TruckPricing implements VehiclePricing{public double charge(int d){return 200*d;}}class Vehicle{String id;VehiclePricing pricing;boolean available=true;Vehicle(String i,VehiclePricing p){id=i;pricing=p;}}class Customer{String name;Customer(String n){name=n;}}class Rental{Vehicle vehicle;Customer customer;Rental(Vehicle v,Customer c){if(!v.available)throw new IllegalStateException();vehicle=v;customer=c;v.available=false;}double charge(int days){return vehicle.pricing.charge(days);}void returned(){vehicle.available=true;}}public class Main{public static void main(String[]a){}}